package com.training.accounting.config;
import com.training.accounting.user.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class BootstrapData implements CommandLineRunner { private final BusinessRepository br; private final AppUserRepository ur; private final PasswordEncoder pe; @Value("${app.bootstrap.admin-email}") String email; @Value("${app.bootstrap.admin-password}") String pwd; @Value("${app.bootstrap.business-name}") String businessName; public BootstrapData(BusinessRepository br,AppUserRepository ur,PasswordEncoder pe){this.br=br;this.ur=ur;this.pe=pe;} @Transactional public void run(String...a){ if(ur.findByEmailIgnoreCase(email).isPresent()) return; Business b=new Business(); b.setName(businessName); b=br.save(b); AppUser u=new AppUser();u.setBusinessId(b.getId());u.setEmail(email);u.setPasswordHash(pe.encode(pwd));u.setRole("ADMIN");u.setActive(true);ur.save(u);} }
